const items = Array.isArray($input.first().json) ? $input.first().json : [];
console.log(`[Metadata] ${items.length} items need enrichment`);
if (!items.length) return [];
return items.map(item => ({ json: item }));

const item = $input.first().json;
const TMDB_KEY = process.env.TMDB_API_KEY;
if (!TMDB_KEY) {
  console.log('[Metadata] TMDB_API_KEY not set — skipping');
  return [{ json: { skipped: true, reason: 'no_tmdb_key' } }];
}

// Search TMDB for this content
const query = encodeURIComponent(item.title_orig || item.title_ar);
const type = item.type === 'film' ? 'movie' : 'tv';
const yearParam = item.year ? `&year=${item.year}` : '';
const url = `https://api.themoviedb.org/3/search/${type}?api_key=${TMDB_KEY}&query=${query}&language=ar${yearParam}`;

try {
  const r = await fetch(url);
  const data = await r.json();
  const result = data.results?.[0];
  if (!result) return [{ json: { skipped: true, id: item.id, reason: 'not_found' } }];

  const patch = {};
  if (result.poster_path) patch.poster_url = `https://image.tmdb.org/t/p/w500${result.poster_path}`;
  if (result.overview && result.overview.length > 20) patch.description = result.overview.slice(0, 1000);
  if (result.vote_average) patch.quality_score = Math.round(result.vote_average * 10);
  const releaseYear = parseInt((result.release_date || result.first_air_date || '').slice(0, 4));
  if (releaseYear && !item.year) patch.year = releaseYear;

  return [{ json: { id: item.id, patch, title: item.title_ar, found: true } }];
} catch(e) {
  console.error('[Metadata] TMDB error:', e.message);
  return [{ json: { skipped: true, id: item.id, reason: 'fetch_error' } }];
}

const items = $input.all();
const updated = items.filter(i => i.json.statusCode === 204 || i.json.statusCode === 200).length;
console.log(`[Metadata] ${updated} items enriched with TMDB data`);
return [{ json: { updated, run_at: new Date().toISOString() } }];
